import { createFileRoute } from "@tanstack/react-router";
import { ProtectedRoute } from "@/components/auth/protected-route";
import { PaymentSuccessPage } from "@/pages/payment-success-page";

export const Route = createFileRoute("/payment-success/$id")({
  component: () => (
    <ProtectedRoute>
      <PaymentSuccessPage />
    </ProtectedRoute>
  ),
});

export type UserRole = "student" | "staff" | "admin";

export type VerificationStatus = "unverified" | "pending" | "verified";

export interface User {
  id: string;
  email: string;
  fullName: string;
  avatarUrl?: string;
  role: UserRole;
  verificationStatus: VerificationStatus;
  university?: string;
  studentNumber?: string;
  faculty?: string;
  campus?: string;
  createdAt: string;
}

export interface AuthSession {
  user: User;
  token: string;
  expiresAt: number;
}

export type DietaryTag = "Vegan" | "Vegetarian" | "Halal" | "Kosher" | "Gluten-Free" | "Spicy";

export interface MenuItem {
  id: string;
  restaurantId: string;
  name: string;
  description: string;
  priceCents: number;
  image: string;
  prepTimeMinutes: number;
  calories?: number;
  dietaryTags: DietaryTag[];
  isPopular?: boolean;
  category: string;
  rating?: number;
  popularityCount?: number;
}

export interface Review {
  id: string;
  restaurantId: string;
  authorName: string;
  authorAvatar?: string;
  rating: number;
  comment: string;
  date: string;
}

export interface Restaurant {
  id: string;
  name: string;
  cuisine: string;
  heroImage: string;
  logoImage?: string;
  rating: number;
  reviewCount: number;
  etaMinutes: number;
  distance: string;
  discountLabel: string;
  studentDiscountPercent?: number;
  categories: string[];
  isOpen: boolean;
  openingHours: { day: string; hours: string }[];
  reviews: Review[];
  menuItems: MenuItem[];
  tags?: string[];
}

export interface CartItem {
  item: MenuItem;
  quantity: number;
}

export type OrderStatus = "pending" | "preparing" | "ready" | "delivered" | "cancelled";
export type OrderType = "delivery" | "pickup";
export type PaymentMethod = "wallet" | "card";

export interface Order {
  id: string;
  items: CartItem[];
  subtotalCents: number;
  studentDiscountCents: number;
  promoDiscountCents: number;
  deliveryFeeCents: number;
  totalCents: number;
  status: OrderStatus;
  orderType: OrderType;
  paymentMethod: PaymentMethod;
  restaurantId: string;
  restaurantName: string;
  createdAt: string;
  estimatedReadyAt: string;
}

export type TransactionType = "topup" | "payment" | "refund" | "reward";

export interface Transaction {
  id: string;
  type: TransactionType;
  amountCents: number;
  description: string;
  date: string;
  merchantName?: string;
}

export type RewardTier = "bronze" | "silver" | "gold" | "diamond";

export interface Reward {
  id: string;
  title: string;
  description: string;
  tier: RewardTier;
  pointsCost: number;
  icon: string;
  isEarned: boolean;
  progressPercent?: number;
}

export interface Challenge {
  id: string;
  title: string;
  description: string;
  points: number;
  progress: number;
  target: number;
  isComplete: boolean;
  timeframe: "daily" | "weekly";
}

export interface WalletState {
  balanceCents: number;
  transactions: Transaction[];
  totalSpentThisMonthCents: number;
  rewardPoints: number;
  tier: RewardTier;
  tierProgressPercent: number;
}

export interface Offer {
  id: string;
  title: string;
  description: string;
  restaurantName: string;
  discountPercent: number;
  expiryDate: string;
  image: string;
  isStudentExclusive: boolean;
}

@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&family=Inter:wght@400;500;600;700&display=swap');
@import "tailwindcss";
@config "../../tailwind.config.js";

/* ── Light mode tokens ─────────────────────────────────────────── */
:root {
  --primary:       #0D9F6E;
  --primary-600:   #0A7A55;
  --accent:        #00C896;
  --background:    #F8FAFC;
  --surface:       #F1F5F9;
  --card:          #FFFFFF;
  --card-elevated: #FFFFFF;
  --border:        rgba(15,23,42,0.08);
  --text:          #111827;
  --text-secondary: #6B7280;
  --muted:         #F1F5F9;
  --muted-fg:      #9CA3AF;
  --success:       #22C55E;
  --warning:       #F59E0B;
  --danger:        #EF4444;
  --rewards:       #FBBF24;
  --dark:          #0F172A;
  --font-sans:     'Inter', system-ui, sans-serif;
  --font-heading:  'Plus Jakarta Sans', system-ui, sans-serif;
  --radius-sm:     0.75rem;
  --radius-md:     1rem;
  --radius-lg:     1.5rem;
  --radius-xl:     2rem;
  --shadow-card:   0 1px 3px rgba(0,0,0,.06), 0 4px 12px rgba(0,0,0,.04);
  --shadow-soft:   0 2px 8px rgba(0,0,0,.08);
  --shadow-lift:   0 8px 24px rgba(0,0,0,.12);
}

/* ── Dark mode tokens — premium OLED black ────────────────────── */
.dark {
  --primary:        #00D27A;
  --primary-600:    #00B86B;
  --accent:         #00E5A8;
  --background:     #050505;
  --surface:        #0B0B0B;
  --card:           #101010;
  --card-elevated:  #181818;
  --border:         rgba(255,255,255,0.06);
  --text:           #FFFFFF;
  --text-secondary: #A8A8A8;
  --muted:          #1A1A1A;
  --muted-fg:       #6E6E6E;
  --success:        #18D26E;
  --warning:        #FFB020;
  --danger:         #FF4D4F;
  --rewards:        #F6C453;
  --dark:           #000000;
  --shadow-card:    0 1px 3px rgba(0,0,0,.6), 0 4px 12px rgba(0,0,0,.5);
  --shadow-soft:    0 2px 8px rgba(0,0,0,.6);
  --shadow-lift:    0 8px 32px rgba(0,0,0,.7), 0 0 0 1px rgba(255,255,255,0.04);
}

/* ── Dev theme ─────────────────────────────────────────────────── */
.dev {
  --primary:        #6366F1;
  --primary-600:    #4F46E5;
  --accent:         #8B5CF6;
  --background:     #F8F8FF;
  --card:           #FFFFFF;
  --text:           #1E1B4B;
  --border:         rgba(99,102,241,0.12);
}

/* ── Base ──────────────────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

body {
  background-color: var(--background);
  color: var(--text);
  font-family: var(--font-sans);
  line-height: 1.6;
  overflow-x: hidden;
}

/* Radial accent glow in dark mode */
.dark body::before {
  content: '';
  position: fixed;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 700px;
  height: 400px;
  background: radial-gradient(ellipse at top, rgba(0, 210, 122, 0.06) 0%, transparent 70%);
  pointer-events: none;
  z-index: 0;
}

/* ── Scrollbar ─────────────────────────────────────────────────── */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: var(--muted-fg);
  border-radius: 999px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--text-secondary);
}

/* ── Selection ─────────────────────────────────────────────────── */
::selection {
  background-color: var(--primary);
  color: #fff;
}

/* ── Focus ──────────────────────────────────────────────────────── */
:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

/* ── Typography ─────────────────────────────────────────────────── */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  line-height: 1.2;
  letter-spacing: -0.02em;
}

/* ── Layout helpers ──────────────────────────────────────────────── */
.page-container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.25rem;
}

/* Sidebar offset on desktop */
@media (min-width: 1024px) {
  .sidebar-offset {
    margin-left: 16rem;
  }
}

/* ── Horizontal scroll snap row ─────────────────────────────────── */
.scroll-snap-x {
  display: flex;
  gap: 0.875rem;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  padding-bottom: 4px;
  scrollbar-width: none;
}
.scroll-snap-x::-webkit-scrollbar {
  display: none;
}
.scroll-snap-x > * {
  scroll-snap-align: start;
  flex-shrink: 0;
}

/* ── Gradient text ───────────────────────────────────────────────── */
.gradient-text {
  background: linear-gradient(135deg, var(--primary), var(--accent));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.gradient-text-gold {
  background: linear-gradient(135deg, #F6C453, #FF9800);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* ── Glass ───────────────────────────────────────────────────────── */
.glass {
  background: rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(16px) saturate(1.5);
  -webkit-backdrop-filter: blur(16px) saturate(1.5);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.glass-light {
  background: rgba(255, 255, 255, 0.75);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.5);
}

/* ── Touch targets ──────────────────────────────────────────────── */
@media (pointer: coarse) {
  button, a, [role="button"] {
    min-height: 44px;
  }
}

/* ── Keyframes ───────────────────────────────────────────────────── */
@keyframes shimmer {
  0%   { background-position: -200% center; }
  100% { background-position: 200% center; }
}

@keyframes float-y {
  0%, 100% { transform: translateY(0); }
  50%       { transform: translateY(-12px); }
}

@keyframes float-y-slow {
  0%, 100% { transform: translateY(0) rotate(0deg); }
  50%       { transform: translateY(-8px) rotate(3deg); }
}

@keyframes pulse-ring {
  0%   { transform: scale(1); opacity: 0.6; }
  100% { transform: scale(1.6); opacity: 0; }
}

@keyframes spin-slow {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}

@keyframes slide-up-fade {
  from { opacity: 0; transform: translateY(20px); }
  to   { opacity: 1; transform: translateY(0); }
}

@keyframes scale-in-bounce {
  0%   { opacity: 0; transform: scale(0.8); }
  70%  { transform: scale(1.04); }
  100% { opacity: 1; transform: scale(1); }
}

@keyframes coin-fly {
  0%   { transform: translateY(0) scale(1); opacity: 1; }
  100% { transform: translateY(-80px) scale(0.5); opacity: 0; }
}

@keyframes glow-pulse {
  0%, 100% { box-shadow: 0 0 20px rgba(0, 210, 122, 0.3); }
  50%       { box-shadow: 0 0 40px rgba(0, 210, 122, 0.6); }
}

@keyframes fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

/* ── Animation utilities ────────────────────────────────────────── */
.animate-float        { animation: float-y 3s ease-in-out infinite; }
.animate-float-slow   { animation: float-y-slow 5s ease-in-out infinite; }
.animate-pulse-ring   { animation: pulse-ring 1.5s ease-out infinite; }
.animate-spin-slow    { animation: spin-slow 8s linear infinite; }
.animate-slide-up     { animation: slide-up-fade 0.4s ease both; }
.animate-scale-in     { animation: scale-in-bounce 0.3s ease both; }
.animate-coin-fly     { animation: coin-fly 0.6s ease both; }
.animate-glow         { animation: glow-pulse 2s ease-in-out infinite; }
.animate-fade         { animation: fade-in 0.3s ease; }

/* ── Page transitions ────────────────────────────────────────────── */
.page-enter {
  opacity: 0;
  transform: translateY(12px);
}
.page-active {
  opacity: 1;
  transform: translateY(0);
  transition: opacity 0.3s ease, transform 0.3s ease;
}

/* ── Neon glow button ────────────────────────────────────────────── */
.btn-neon {
  box-shadow: 0 0 0 0 rgba(0, 210, 122, 0);
  transition: box-shadow 0.3s ease;
}
.btn-neon:hover {
  box-shadow: 0 0 20px rgba(0, 210, 122, 0.4), 0 0 40px rgba(0, 210, 122, 0.15);
}
.btn-neon:active {
  box-shadow: 0 0 10px rgba(0, 210, 122, 0.3);
}

/* Developer theme adjustments */
.dev {
  --color-primary: #006bff;
  --color-primary-600: #004bb5;
  --color-background: #0b1020;
  --color-card: #0f1723;
  --color-text: #e6eef8;
  --font-heading: "Courier New", ui-monospace, SFMono-Regular, Menlo, Monaco, "Roboto Mono", "Noto Mono", monospace;
}

.dev .font-heading { font-family: var(--font-heading); }
.dev .bg-card { background: var(--color-card); }
.dev .text-primary { color: var(--color-primary); }
.dev .bg-primary { background: var(--color-primary); }
.dev .shadow-lift { box-shadow: 0 12px 40px rgba(0, 107, 255, 0.14); }

.dev pre, .dev code {
  background: rgba(0,0,0,0.25);
  padding: 0.25rem 0.5rem;
  border-radius: 6px;
  font-family: var(--font-heading);
}

import { useState } from "react";
import { Link, useNavigate } from "@/lib/router-compat";
import { motion } from "framer-motion";
import { Mail, Lock, User as UserIcon, ArrowLeft, GraduationCap, CircleCheck as CheckCircle2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Checkbox } from "@/components/ui/selection-controls";
import { useAuth } from "@/contexts/auth-context";
import { useToast } from "@/contexts/toast-context";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";

type AuthMode = "login" | "register" | "forgot";

export function AuthPage({ mode }: { mode: AuthMode }) {
  const navigate = useNavigate();
  const { login, register, forgotPassword } = useAuth();
  const { showToast } = useToast();
  const reduced = usePrefersReducedMotion();

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [fullName, setFullName] = useState("");
  const [rememberMe, setRememberMe] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState("");
  const [emailSent, setEmailSent] = useState(false);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError("");
    setIsLoading(true);

    try {
      if (mode === "login") {
        await login(email, password, rememberMe);
        showToast("Welcome back!", "success");
        navigate("/home");
      } else if (mode === "register") {
        if (!fullName.trim()) throw new Error("Please enter your full name.");
        await register(email, password, fullName, rememberMe);
        showToast("Account created! Check your email for verification.", "success");
        navigate("/home");
      } else {
        await forgotPassword(email);
        setEmailSent(true);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Something went wrong. Please try again.");
    } finally {
      setIsLoading(false);
    }
  }

  const titles = {
    login: { eyebrow: "Welcome back", title: "Sign in to PayPlate", desc: "Your campus food wallet is waiting." },
    register: { eyebrow: "Join PayPlate", title: "Create your account", desc: "Student-exclusive deals, wallet, and rewards." },
    forgot: { eyebrow: "Reset password", title: "Forgot your password?", desc: "We'll send you a reset link." },
  };

  const t = titles[mode];

  return (
    <div className="grid min-h-screen lg:grid-cols-2">
      {/* Left visual panel */}
      <div className="relative hidden overflow-hidden bg-gradient-to-br from-primary via-primary-600 to-dark lg:block">
        <div className="absolute inset-0">
          <div className="absolute -left-20 top-20 size-72 rounded-full bg-white/10 blur-3xl" />
          <div className="absolute -right-20 bottom-20 size-72 rounded-full bg-white/5 blur-3xl" />
          <motion.div
            animate={reduced ? undefined : { y: [0, -20, 0] }}
            transition={{ duration: 4, repeat: Infinity, ease: "easeInOut" }}
            className="absolute left-1/2 top-1/3 -translate-x-1/2"
          >
            <div className="rounded-3xl bg-white/15 p-8 backdrop-blur-md">
              <GraduationCap size={48} className="text-white" />
            </div>
          </motion.div>
        </div>
        <div className="relative flex h-full flex-col justify-end p-12">
          <h2 className="font-heading text-4xl font-black text-white">Campus food, simplified.</h2>
          <p className="mt-3 max-w-md text-white/80">
            Order from your favourite campus restaurants, pay with your wallet, and earn rewards on every purchase.
          </p>
        </div>
      </div>

      {/* Right form panel */}
      <div className="flex items-center justify-center p-6 lg:p-12">
        <div className="w-full max-w-sm">
          <Link to="/" className="mb-8 inline-flex items-center gap-2 text-sm font-bold text-muted-foreground hover:text-text">
            <ArrowLeft size={16} /> Back home
          </Link>

          <p className="text-sm font-bold text-primary">{t.eyebrow}</p>
          <h1 className="mt-1 font-heading text-3xl font-black">{t.title}</h1>
          <p className="mt-2 text-sm text-muted-foreground">{t.desc}</p>

          {mode === "forgot" && emailSent ? (
            <div className="mt-8 rounded-2xl border border-border bg-card p-6 text-center">
              <CheckCircle2 size={40} className="mx-auto text-success" />
              <h3 className="mt-4 font-heading text-lg font-black">Check your inbox</h3>
              <p className="mt-2 text-sm text-muted-foreground">
                If an account exists for {email}, we've sent a password reset link.
              </p>
              <Link to="/login">
                <Button variant="secondary" className="mt-6 w-full">Back to sign in</Button>
              </Link>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="mt-8 space-y-4">
              {mode === "register" && (
                <Input
                  label="Full name"
                  name="fullName"
                  placeholder="Jane Doe"
                  icon={<UserIcon size={18} />}
                  value={fullName}
                  onChange={(e) => setFullName(e.target.value)}
                  required
                />
              )}

              <Input
                label="Email"
                name="email"
                type="email"
                placeholder="jane@university.ac.za"
                icon={<Mail size={18} />}
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
              />

              {mode !== "forgot" && (
                <Input
                  label="Password"
                  name="password"
                  type="password"
                  placeholder="••••••••"
                  icon={<Lock size={18} />}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                />
              )}

              {mode === "login" && (
                <div className="flex items-center justify-between">
                  <Checkbox checked={rememberMe} onChange={setRememberMe} label="Remember me" />
                  <Link to="/forgot-password" className="text-sm font-bold text-primary hover:underline">
                    Forgot password?
                  </Link>
                </div>
              )}

              {error && (
                <div className="rounded-xl bg-danger/10 px-4 py-3 text-sm font-bold text-danger">
                  {error}
                </div>
              )}

              <Button type="submit" disabled={isLoading} className="w-full">
                {isLoading ? "Please wait…" : mode === "login" ? "Sign in" : mode === "register" ? "Create account" : "Send reset link"}
              </Button>
            </form>
          )}

          {mode === "login" && (
            <p className="mt-6 text-center text-sm text-muted-foreground">
              Don't have an account?{" "}
              <Link to="/register" className="font-bold text-primary hover:underline">Sign up</Link>
            </p>
          )}
          {mode === "register" && (
            <p className="mt-6 text-center text-sm text-muted-foreground">
              Already have an account?{" "}
              <Link to="/login" className="font-bold text-primary hover:underline">Sign in</Link>
            </p>
          )}
          {mode === "forgot" && !emailSent && (
            <p className="mt-6 text-center text-sm text-muted-foreground">
              Remembered it?{" "}
              <Link to="/login" className="font-bold text-primary hover:underline">Back to sign in</Link>
            </p>
          )}
        </div>
      </div>
    </div>
  );
}

import { useNavigate } from "@/lib/router-compat";
import { motion } from "framer-motion";
import { Plus, Minus, Trash2, ShoppingBag, ArrowRight, Tag, GraduationCap } from "lucide-react";
import { AppShell } from "@/components/layout/app-shell";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { EmptyState } from "@/components/ui/empty-state";
import { useCart } from "@/contexts/cart-context";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";
import { formatRand } from "@/services/payplate-data";
import { useState } from "react";

export function CartPage() {
  const navigate = useNavigate();
  const { items, updateQuantity, removeItem, subtotalCents, studentDiscountCents, deliveryFeeCents, totalCents, itemCount } = useCart();
  const reduced = usePrefersReducedMotion();
  const [promoCode, setPromoCode] = useState("");
  const [promoApplied, setPromoApplied] = useState(false);
  const [promoError, setPromoError] = useState("");

  function applyPromo() {
    if (!promoCode.trim()) return;
    if (promoCode.toUpperCase() === "STUDENT10") {
      setPromoApplied(true);
      setPromoError("");
    } else {
      setPromoError("Invalid promo code. Try STUDENT10.");
      setPromoApplied(false);
    }
  }

  if (items.length === 0) {
    return (
      <AppShell>
        <EmptyState
          icon={<ShoppingBag size={32} />}
          title="Your cart is empty"
          description="Browse restaurants and add meals to get started."
          action={<Button onClick={() => navigate("/restaurants")}>Browse restaurants</Button>}
        />
      </AppShell>
    );
  }

  const promoDiscount = promoApplied ? Math.round(subtotalCents * 0.1) : 0;
  const finalTotal = totalCents - promoDiscount;

  return (
    <AppShell>
      <div className="space-y-6">
        <div>
          <h1 className="font-heading text-2xl font-black lg:text-3xl">Your cart</h1>
          <p className="mt-1 text-sm text-muted-foreground">{itemCount} item{itemCount > 1 ? "s" : ""}</p>
        </div>

        <div className="grid gap-6 lg:grid-cols-3">
          {/* Items */}
          <div className="space-y-3 lg:col-span-2">
            {items.map((ci, i) => (
              <motion.div
                key={ci.item.id}
                initial={reduced ? undefined : { opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: 20 }}
                transition={{ delay: i * 0.05 }}
              >
                <Card className="grid grid-cols-[80px_1fr_auto] items-center gap-4 p-3">
                  <img src={ci.item.image} alt={ci.item.name} className="aspect-square w-full rounded-xl object-cover" />
                  <div className="min-w-0">
                    <h3 className="truncate font-heading font-black">{ci.item.name}</h3>
                    <p className="text-sm text-muted-foreground">{formatRand(ci.item.priceCents)} each</p>
                    <div className="mt-2 flex items-center gap-2">
                      <button
                        onClick={() => updateQuantity(ci.item.id, ci.quantity - 1)}
                        className="grid size-8 place-items-center rounded-lg bg-muted"
                        aria-label="Decrease"
                      >
                        <Minus size={14} />
                      </button>
                      <span className="min-w-6 text-center font-heading font-black tabular-nums">{ci.quantity}</span>
                      <button
                        onClick={() => updateQuantity(ci.item.id, ci.quantity + 1)}
                        className="grid size-8 place-items-center rounded-lg bg-primary text-white"
                        aria-label="Increase"
                      >
                        <Plus size={14} />
                      </button>
                    </div>
                  </div>
                  <div className="flex flex-col items-end gap-2">
                    <p className="font-heading font-black tabular-nums">{formatRand(ci.item.priceCents * ci.quantity)}</p>
                    <button
                      onClick={() => removeItem(ci.item.id)}
                      className="grid size-8 place-items-center rounded-lg text-muted-foreground hover:bg-danger/10 hover:text-danger"
                      aria-label="Remove item"
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>
                </Card>
              </motion.div>
            ))}
          </div>

          {/* Summary */}
          <div className="space-y-4">
            <Card>
              <h3 className="font-heading text-lg font-black">Order summary</h3>

              {/* Promo code */}
              <div className="mt-4">
                <div className="flex gap-2">
                  <Input
                    placeholder="Promo code"
                    value={promoCode}
                    onChange={(e) => setPromoCode(e.target.value)}
                    icon={<Tag size={16} />}
                  />
                  <Button variant="secondary" onClick={applyPromo} className="whitespace-nowrap">Apply</Button>
                </div>
                {promoError && <p className="mt-2 text-xs font-bold text-danger">{promoError}</p>}
                {promoApplied && <p className="mt-2 text-xs font-bold text-success">10% promo applied!</p>}
              </div>

              <div className="mt-4 space-y-2 border-t border-border pt-4 text-sm">
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Subtotal</span>
                  <span className="font-bold tabular-nums">{formatRand(subtotalCents)}</span>
                </div>
                <div className="flex justify-between text-success">
                  <span className="inline-flex items-center gap-1"><GraduationCap size={14} /> Student discount (15%)</span>
                  <span className="font-bold tabular-nums">−{formatRand(studentDiscountCents)}</span>
                </div>
                {promoApplied && (
                  <div className="flex justify-between text-success">
                    <span>Promo (STUDENT10)</span>
                    <span className="font-bold tabular-nums">−{formatRand(promoDiscount)}</span>
                  </div>
                )}
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Delivery fee</span>
                  <span className="font-bold tabular-nums">{formatRand(deliveryFeeCents)}</span>
                </div>
              </div>

              <div className="mt-4 flex items-center justify-between border-t border-border pt-4">
                <span className="font-heading text-lg font-black">Total</span>
                <motion.span
                  key={finalTotal}
                  initial={reduced ? undefined : { scale: 1.1 }}
                  animate={{ scale: 1 }}
                  className="font-heading text-2xl font-black text-primary tabular-nums"
                >
                  {formatRand(finalTotal)}
                </motion.span>
              </div>

              <Button className="mt-4 w-full" onClick={() => navigate("/checkout")}>
                Proceed to checkout <ArrowRight size={18} />
              </Button>
            </Card>

            <p className="text-center text-xs text-muted-foreground">
              You're saving {formatRand(studentDiscountCents + promoDiscount)} with student discounts
            </p>
          </div>
        </div>
      </div>
    </AppShell>
  );
}
